const studentRecipients = `-- name: StudentRecipients :many
SELECT u FROM (
    SELECT s.user_id AS u FROM academic.students s WHERE s.id = $1 AND s.user_id IS NOT NULL
    UNION ALL
    SELECT g.guardian_id FROM academic.student_guardians g
    WHERE g.student_id = $1
      AND NOT EXISTS (SELECT 1 FROM academic.students s WHERE s.id = $1 AND s.user_id IS NOT NULL)
) x WHERE u IS NOT NULL
`

// Người nhận thông báo cổng của học viên: tài khoản học viên, chưa có thì phụ huynh.
func (q *Queries) StudentRecipients(ctx context.Context, studentID uuid.UUID) ([]*uuid.UUID, error) {
	rows, err := q.db.Query(ctx, studentRecipients, studentID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []*uuid.UUID
	for rows.Next() {
		var u *uuid.UUID
		if err := rows.Scan(&u); err != nil {
			return nil, err
		}
		items = append(items, u)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const teacherCoversStudent = `-- name: TeacherCoversStudent :one
SELECT EXISTS (
    SELECT 1 FROM academic.classes c
    WHERE c.deleted_at IS NULL
      AND ($1::bool OR c.teacher_id = $2 OR c.assistant_id = $2
           OR c.foreign_teacher_id = $2)
      AND (c.id = (SELECT s.current_class_id FROM academic.students s WHERE s.id = $3)
           OR c.id IN (SELECT e.class_id FROM academic.enrollments e WHERE e.student_id = $3
                       AND e.status IN ('pending', 'completed') AND e.left_at IS NULL))
)
`

type TeacherCoversStudentParams struct {
	AllClasses bool
	UserID     *uuid.UUID
	StudentID  uuid.UUID
}

// Giáo viên chấm được bài của học viên: học viên thuộc (một) lớp giáo viên phụ trách (markSubmission).
func (q *Queries) TeacherCoversStudent(ctx context.Context, arg TeacherCoversStudentParams) (bool, error) {
	row := q.db.QueryRow(ctx, teacherCoversStudent, arg.AllClasses, arg.UserID, arg.StudentID)
	var exists bool
	err := row.Scan(&exists)
	return exists, err
}

const unreadForUser = `-- name: UnreadForUser :one
SELECT count(*)::int FROM core.notifications n
WHERE n.read_at IS NULL
  AND (n.user_id = $1
       OR n.user_id IN (SELECT s.user_id FROM academic.students s
                        JOIN academic.student_guardians g ON g.student_id = s.id
                        WHERE g.guardian_id = $1 AND s.user_id IS NOT NULL AND s.deleted_at IS NULL))
`

// Chuông của tài khoản cổng: chưa đọc của mọi học viên gắn với tài khoản + của chính tài khoản
// (PortalNotifications::unreadCountForUser).
func (q *Queries) UnreadForUser(ctx context.Context, userID uuid.UUID) (int32, error) {
	row := q.db.QueryRow(ctx, unreadForUser, userID)
	var column_1 int32
	err := row.Scan(&column_1)
	return column_1, err
}

const upcomingSessions = `-- name: UpcomingSessions :many
SELECT cs.id, cs.date, to_char(cs.start_time, 'HH24:MI')::text AS start_time, to_char(cs.end_time, 'HH24:MI')::text AS end_time, cs.type, cs.status, coalesce(cs.room, c.room) AS room, c.name AS class_name
FROM academic.class_sessions cs
JOIN academic.classes c ON c.id = cs.class_id
WHERE cs.class_id = ANY ($1::uuid[]) AND cs.type IN ('regular', 'makeup')
  AND cs.date BETWEEN $2 AND $3
ORDER BY cs.date, cs.start_time
LIMIT 20
`

